import { act, cleanup, fireEvent, render, screen, waitFor } from '@testing-library/react'
import { afterEach, describe, expect, it } from 'vitest'
import { App } from './App'
import { KEYS, PersistentStore } from './data/storage'
import { SyncEngine } from './data/syncEngine'
import { formatLocalTime } from './domain/time'
import { FakeServer } from './testing/fakeServer'
import { MemoryStorage } from './testing/memoryStorage'

const NAME_ERROR = "Name must be 1-32 characters: letters, digits, '_' or '-'."

let engines: SyncEngine[] = []

function mount(options: { identity?: string; server?: FakeServer } = {}) {
  const kv = new MemoryStorage()
  if (options.identity) kv.setItem(KEYS.identity, options.identity)
  const server = options.server ?? new FakeServer()
  const store = new PersistentStore(kv)
  let n = 0
  const engine = new SyncEngine({
    fetchFn: server.fetch,
    baseUrl: 'http://server.test',
    storage: store,
    randomUUID: () => `${String(++n).padStart(8, '0')}-0000-4000-8000-000000000000`,
  })
  engines.push(engine)
  engine.start()
  render(<App store={store} engine={engine} />)
  return { kv, server, store, engine }
}

const byId = (id: string) => screen.getByTestId(id)
const maybe = (id: string) => screen.queryByTestId(id)
const type = (id: string, value: string) => fireEvent.change(byId(id), { target: { value } })
const click = (id: string) => fireEvent.click(byId(id))

function openThread(peer: string) {
  type('new-conversation-peer', peer)
  click('new-conversation-open')
}

afterEach(() => {
  cleanup()
  for (const e of engines) e.stop()
  engines = []
})

describe('startup routing and login', () => {
  it('REQ-ID-001 without a persisted identity shows Login and the engine does not run', () => {
    const { engine, server } = mount()
    expect(byId('login-name')).toHaveProperty('placeholder', 'Your name')
    expect(byId('login-submit').textContent).toBe('Continue')
    expect(maybe('login-error')).toBeNull()
    expect(engine.isRunning()).toBe(false)
    expect(server.requests).toHaveLength(0)
  })

  it('REQ-ID-001 with a persisted identity shows Conversations directly and starts the engine', async () => {
    const { engine } = mount({ identity: 'Alice' })
    expect(byId('me-name').textContent).toBe('Alice')
    expect(engine.isRunning()).toBe(true)
    await waitFor(() => expect(byId('connection-status').textContent).toBe('online'))
    expect(byId('queued-count').textContent).toBe('0 queued')
    expect(byId('conversations-empty').textContent).toBe('No conversations yet.')
    expect(byId('logout').textContent).toBe('Log out')
    expect(byId('new-conversation-peer')).toHaveProperty('placeholder', 'Send to (name)')
    expect(byId('new-conversation-open').textContent).toBe('Open')
  })

  it.each(['   ', 'bad name!'])('REQ-ID-002 an invalid name %j shows the exact error and persists nothing', (name) => {
    const { kv } = mount()
    type('login-name', name)
    click('login-submit')
    expect(byId('login-error').textContent).toBe(NAME_ERROR)
    expect(maybe('me-name')).toBeNull()
    expect(kv.data.size).toBe(0)
  })

  it('REQ-ID-003 a valid name logs in locally (even offline) with the normalized name via Enter', async () => {
    const server = new FakeServer()
    server.setOnline(false)
    const { kv, engine } = mount({ server })
    type('login-name', '  Alice  ')
    fireEvent.submit(byId('login-name').closest('form') as HTMLFormElement)
    expect(byId('me-name').textContent).toBe('Alice')
    expect(kv.getItem(KEYS.identity)).toBe('Alice')
    expect(engine.isRunning()).toBe(true)
    expect(byId('connection-status').textContent).toBe('offline')
  })

  it('REQ-ID-004 logout stops the engine, deletes all local state and shows an empty Login', async () => {
    const server = new FakeServer()
    server.deliver({ from: 'Bob', to: 'Alice', body: 'hi' })
    const { kv, engine } = mount({ identity: 'Alice', server })
    await waitFor(() => expect(screen.getAllByTestId('conversation-row')).toHaveLength(1))
    click('logout')
    expect(engine.isRunning()).toBe(false)
    expect(kv.data.size).toBe(0)
    expect(byId('login-name')).toHaveProperty('value', '')
    expect(server.gets.at(-1)?.signal.aborted).toBe(true)
  })

  it('REQ-ID-005 logging in again after logout restores history from the server', async () => {
    const server = new FakeServer()
    server.deliver({ from: 'Alice', to: 'Bob', body: 'hello' })
    const { store } = mount({ identity: 'Alice', server })
    await waitFor(() => expect(store.getSnapshot().messages).toHaveLength(1))
    click('logout')
    expect(store.getSnapshot().messages).toHaveLength(0)
    type('login-name', 'Alice')
    click('login-submit')
    await waitFor(() => expect(byId('conversation-preview').textContent).toBe('hello'))
  })
})

describe('conversations', () => {
  it('REQ-ORDER-002 lists conversations newest first with the last message preview', async () => {
    const server = new FakeServer()
    server.deliver({ from: 'Bob', to: 'Alice', body: 'from bob' })
    server.deliver({ from: 'Carol', to: 'Alice', body: 'from carol' })
    mount({ identity: 'Alice', server })
    await waitFor(() => expect(screen.getAllByTestId('conversation-row')).toHaveLength(2))
    expect(screen.getAllByTestId('conversation-peer').map((e) => e.textContent)).toEqual(['Carol', 'Bob'])
    act(() => {
      server.deliver({ from: 'Bob', to: 'Alice', body: 'bob again' })
    })
    await waitFor(() =>
      expect(screen.getAllByTestId('conversation-preview').map((e) => e.textContent)).toEqual(['bob again', 'from carol']),
    )
    expect(maybe('conversations-empty')).toBeNull()
  })

  it('REQ-UI-006 validates the peer name and refuses myself', () => {
    mount({ identity: 'Alice' })
    openThread('no spaces')
    expect(byId('new-conversation-error').textContent).toBe(NAME_ERROR)
    openThread(' Alice ')
    expect(byId('new-conversation-error').textContent).toBe('You cannot message yourself.')
    openThread('  Bob ')
    expect(byId('thread-peer').textContent).toBe('Bob')
    expect(byId('thread-empty').textContent).toBe('No messages yet.')
    expect(byId('thread-back').textContent).toBe('Back')
    click('thread-back')
    expect(byId('new-conversation-peer')).toHaveProperty('value', '')
    expect(maybe('new-conversation-error')).toBeNull()
  })

  it('REQ-UI-001 tapping a conversation row opens that thread', async () => {
    const server = new FakeServer()
    server.deliver({ from: 'Bob', to: 'Alice', body: 'hey' })
    mount({ identity: 'Alice', server })
    await waitFor(() => expect(screen.getAllByTestId('conversation-row')).toHaveLength(1))
    fireEvent.click(byId('conversation-row'))
    expect(byId('thread-peer').textContent).toBe('Bob')
    expect(byId('message-body').textContent).toBe('hey')
  })
})

describe('thread and composer', () => {
  it('REQ-SEND-001 invalid bodies show the exact error, create nothing and keep the input', () => {
    const { store } = mount({ identity: 'Alice' })
    openThread('Bob')
    expect(byId('composer-input')).toHaveProperty('placeholder', 'Message')
    expect(byId('composer-send').textContent).toBe('Send')
    type('composer-input', '   ')
    click('composer-send')
    expect(byId('composer-error').textContent).toBe('Message cannot be empty.')
    expect(byId('composer-input')).toHaveProperty('value', '   ')
    type('composer-input', 'x'.repeat(1001))
    click('composer-send')
    expect(byId('composer-error').textContent).toBe('Message is too long (max 1000 characters).')
    expect(store.getSnapshot().messages).toHaveLength(0)
  })

  it('REQ-SEND-003 a valid send is persisted, clears the input, hides the error and keeps focus', async () => {
    const { store, kv } = mount({ identity: 'Alice' })
    await waitFor(() => expect(byId('connection-status').textContent).toBe('online'))
    openThread('Bob')
    type('composer-input', '')
    click('composer-send')
    expect(maybe('composer-error')).not.toBeNull()
    const input = byId('composer-input')
    input.focus()
    type('composer-input', ' hello ')
    click('composer-send')
    expect(input).toHaveProperty('value', '')
    expect(maybe('composer-error')).toBeNull()
    expect(document.activeElement).toBe(input)
    expect(store.getSnapshot().messages[0].body).toBe(' hello ')
    expect(kv.getItem(KEYS.messages)).toContain(' hello ')
    await waitFor(() => expect(byId('message-status').textContent).toBe('sent'))
    expect(byId('queued-count').textContent).toBe('0 queued')
  })

  it('REQ-OUTBOX-003 while offline a sent message shows as queued and is counted', async () => {
    const server = new FakeServer()
    server.setOnline(false)
    mount({ identity: 'Alice', server })
    openThread('Bob')
    type('composer-input', 'later')
    click('composer-send')
    expect(byId('message-status').textContent).toBe('queued')
    expect(byId('queued-count').textContent).toBe('1 queued')
    expect(byId('connection-status').textContent).toBe('offline')
    expect(maybe('thread-empty')).toBeNull()
  })

  it('REQ-SYNC-004 a message row shows from, body (or Unsupported message), status and HH:mm time', async () => {
    const server = new FakeServer()
    const plain = server.deliver({ from: 'Bob', to: 'Alice', body: 'plain' })
    server.deliver({ from: 'Bob', to: 'Alice', body: 'secret', kind: 'sticker' })
    mount({ identity: 'Alice', server })
    await waitFor(() => expect(screen.getAllByTestId('conversation-row')).toHaveLength(1))
    expect(byId('conversation-preview').textContent).toBe('Unsupported message')
    fireEvent.click(byId('conversation-row'))
    const rows = screen.getAllByTestId('message-row')
    expect(rows).toHaveLength(2)
    const texts = (id: string) => screen.getAllByTestId(id).map((e) => e.textContent)
    expect(texts('message-from')).toEqual(['Bob', 'Bob'])
    expect(texts('message-body')).toEqual(['plain', 'Unsupported message'])
    expect(texts('message-status')).toEqual(['received', 'received'])
    expect(texts('message-time')[0]).toBe(formatLocalTime(plain.receivedAt))
    expect(texts('message-time')[0]).toMatch(/^\d{2}:\d{2}$/)
  })
})
